function rooms_validate_insert(array $data): array
{
    $errors = [];
    if (!array_key_exists('property_id', $data) || $data['property_id'] === null || $data['property_id'] === '') {
        $errors['property_id'] = 'required';
    }
    if (isset($data['property_id']) && $data['property_id'] !== null && !ctype_digit((string)$data['property_id'])) {
        $errors['property_id'] = 'must be an integer';
    }
    if (!array_key_exists('capacity', $data) || $data['capacity'] === null || $data['capacity'] === '') {
        $errors['capacity'] = 'required';
    }
    if (isset($data['capacity']) && $data['capacity'] !== null && !ctype_digit((string)$data['capacity'])) {
        $errors['capacity'] = 'must be an integer';
    }
    if (!array_key_exists('price', $data) || $data['price'] === null || $data['price'] === '') {
        $errors['price'] = 'required';
    }
    return $errors;
}

